%% Radial Average
function Rx = radial_average(X)
    % Given a (2N-1)x(2N-1) matrix of 2D correlations (i.e. as generated by
    % X = xcorr2(im) where im is a NxN image), compute averages over
    % all points (j,k) with equal distance r = sqrt((j-N)^2 + (k - N)^2) from
    % the center entry (N,N) of the matrix.
    [P, Q] = size(X);
    if P ~= Q || rem(P, 2) ~= 1
        error("Matrix X must be of dimension (2N - 1)x(2N - 1) for some N>0.")
    end
    N = (P + 1) / 2;
    M = floor(N * sqrt(2)) + 1;
    sums = zeros(M, 1);
    counts = zeros(M, 1);
    for j = 1:P
        for k = 1:P
            d = sqrt((j-N)^2 + (k-N)^2);
            d_index = floor(d) + 1;
            sums(d_index) = sums(d_index) + X(j,k);
            counts(d_index) = counts(d_index) + 1;
        end
    end
    % Each distance will correspond to at least one entry of X, 
    % so divide by 0 isn't a concern.
    Rx = sums ./ counts;

end

function Rxx = autocov(x)
    [N, M] = size(x);
    if N ~= M
        error("input must be square")
    end
    Rxx = xcorr2(x);
    % Divide correlation by the number of
    % samples averaged over to compute the sample
    % covariance.
    counts = zeros(size(Rxx));
    for i = 1:(2*N-1)
        for j = 1:(2*N-1)
            count_x = min(N, i) - max(0, i - N);
            count_y = min(N, j) - max(0, j - N);
            counts(i,j) = count_x * count_y;
        end
    end
    Rxx = Rxx ./ counts;
end

