%% New radial estimate about a single point
function Rx = radial_correlation(X, ci, cj)
    % Given a MxN matrix of 2D correlations, compute the
    % expectation E[xy] where x = X(ci, cj) is the evaluation at some
    % center point of the image X and y = X(i,j) is the set of points a
    % distance r = sqrt((i-ci)^2 + (j-cj)^2) from the given center point.
    [M, N] = size(X);
    if ci > M || ci < 1
        error("ci must be in interval [1,M] where M = size(X,1).")
    elseif cj > N || cj < 1
        error("cj must be in interval [1,N] where N = size(X,2).")
    end

    max_x_dist = max(ci, M-ci);
    max_y_dist = max(cj, M-cj);
    D = floor(sqrt(max_x_dist^2 + max_y_dist^2)) + 1;

    sums = zeros(D, 1);
    counts = zeros(D, 1);
    for i = 1:M
        for j = 1:N
            d = sqrt((i - ci)^2 + (j - cj)^2);
            d_index = floor(d) + 1;
            sums(d_index) = sums(d_index) + X(ci, cj) * conj(X(i,j));
            counts(d_index) = counts(d_index) + 1;
        end
    end
    % Each distance will correspond to at least one entry of X, 
    % so divide by 0 isn't a concern.
    Rx = sums ./ counts;
    % Rx = sums;
end

