%% Compute SNR
function Rxx = xcorr2_same(x)
    [N, M] = size(x);
    % Output size will be (2N - 1) x (2M - 1) with the (N,M) entry
    % corresponding to Rxx(\tau=0, \mu=0). We therefore select
    % indices (N - floor(N/2)) <= \tau < (N + ceil(N/2)) which correspond
    % to the greatest overlap
    Rxx = xcorr2(x);
    Rxx = Rxx( ...
        N - floor(N/2) : N + ceil(N/2) - 1,    ...
        M - floor(M/2) : M + ceil(M/2) - 1     ...
    );
end

function Sxx = spectrum2d(x)
    [N, M] = size(x);
    Rxx = xcorr2_same(x);
    Sxx = fftshift(abs(fft2(Rxx)));
    % Normalize by power
    P = Rxx(floor(N/2) + 1, floor(M/2) + 1);
    Sxx = Sxx * P / sum(sum(Sxx));
end

